-- 60 more words, one per day from 2026-11-15. Audio is left empty on purpose:
-- the app falls back to the browser's built-in voice when no mp3 is set.
insert into public.words (word, pronunciation, definition, example_sentence, category, publish_date, styles, level)
select v.word, v.pron, v.def, v.ex, 'vocabulary', date '2026-11-15' + v.d, v.styles, v.level
from (values
 (0,  'Curious',      'KYOOR-ee-us',        'Eager to learn or know something.', 'Her curious mind never stopped asking why.', array['everyday','writer'], 'beginner'),
 (1,  'Laconic',      'luh-KON-ik',         'Using very few words.', 'His laconic reply was just one word: "Fine."', array['writer','exam'], 'advanced'),
 (2,  'Diligent',     'DIL-ih-jent',        'Careful and hard-working in everything you do.', 'A diligent student, she reviewed her notes every night.', array['everyday','business','exam'], 'intermediate'),
