 (9,  'Ineffable',    'in-EF-uh-bul',       'Too great or beautiful to be put into words.', 'They felt an ineffable joy as the sun rose.', array['writer','exam'], 'advanced'),
 (10, 'Plausible',    'PLAW-zuh-bul',       'Seeming reasonable and likely to be true.', 'His excuse sounded plausible, but nobody could check it.', array['everyday','business','exam'], 'intermediate'),
 (11, 'Thrive',       'THRYV',              'To grow and do well.', 'Plants thrive when they get enough light.', array['everyday'], 'beginner'),
 (12, 'Eclectic',     'ih-KLEK-tik',        'Drawn from a wide variety of sources or styles.', 'Her eclectic playlist runs from jazz to metal.', array['writer','everyday'], 'intermediate'),
 (13, 'Perfunctory',  'per-FUNK-tuh-ree',   'Done as a duty, with little interest or care.', 'He gave the report a perfunctory glance.', array['exam','business'], 'advanced'),
 (14, 'Eager',        'EE-ger',             'Keen and excited to do something.', 'The kids were eager to start the trip.', array['everyday'], 'beginner'),
 (15, 'Ambiguous',    'am-BIG-yoo-us',      'Open to more than one meaning; unclear.', 'The ambiguous email left everyone confused.', array['business','exam'], 'intermediate'),
 (16, 'Vivid',        'VIV-id',             'Strong, clear, and full of life.', 'I have a vivid memory of my first day at school.', array['writer','everyday'], 'beginner'),
 (17, 'Obfuscate',    'OB-fuh-skayt',       'To make something deliberately unclear or confusing.', 'The contract''s jargon seemed meant to obfuscate the fees.', array['exam','business'], 'advanced'),
 (18, 'Benevolent',   'buh-NEV-uh-lent',    'Kind, generous, and well-meaning.', 'A benevolent donor paid for the new library.', array['writer','exam'], 'intermediate'),
 (19, 'Hesitate',     'HEZ-ih-tayt',        'To pause before doing something because you are unsure.', 'Don''t hesitate to ask if you need help.', array['everyday','business'], 'beginner'),
