 (24, 'Magnanimous',  'mag-NAN-ih-mus',     'Generous and forgiving, especially toward a rival.', 'The champion was magnanimous in victory.', array['writer','exam'], 'advanced'),
 (25, 'Stubborn',     'STUB-ern',           'Unwilling to change your mind or way of doing things.', 'My stubborn old car refuses to start in the cold.', array['everyday'], 'beginner'),
 (26, 'Adept',        'uh-DEPT',            'Very skilled at something.', 'She is adept at solving tricky customer problems.', array['business','everyday'], 'intermediate'),
 (27, 'Quixotic',     'kwik-SOT-ik',        'Idealistic in a way that is unrealistic or impractical.', 'Their quixotic plan was to row across the ocean.', array['writer','exam'], 'advanced'),
