 (31, 'Tranquil',     'TRANG-kwil',         'Calm, peaceful, and free from disturbance.', 'The lake was tranquil at dawn.', array['writer','everyday'], 'beginner'),
 (32, 'Embellish',    'im-BEL-ish',         'To make something more attractive by adding details, often untrue ones.', 'He tends to embellish his travel stories.', array['writer','everyday'], 'intermediate'),
 (33, 'Zeitgeist',    'ZYT-gyst',           'The mood or spirit of a particular time.', 'The film captured the zeitgeist of the 1990s.', array['writer','exam'], 'advanced'),
 (34, 'Candid',       'KAN-did',            'Honest and direct, even if it is uncomfortable.', 'I appreciate your candid feedback.', array['everyday','business'], 'beginner'),
 (35, 'Formidable',   'FOR-mih-duh-bul',    'Inspiring fear or respect because of size or ability.', 'Their chess champion was a formidable opponent.', array['exam','writer'], 'intermediate'),
 (36, 'Truculent',    'TRUK-yoo-lent',      'Eager to argue or fight; aggressive.', 'The truculent customer demanded to see the manager.', array['exam','writer'], 'advanced'),
 (37, 'Persuade',     'per-SWAYD',          'To convince someone to do or believe something.', 'She managed to persuade him to join the club.', array['everyday','business'], 'beginner'),
 (38, 'Gregarious',   'grih-GAIR-ee-us',    'Sociable and fond of company.', 'A gregarious host, he greeted every guest by name.', array['everyday','writer'], 'intermediate'),
 (39, 'Recalcitrant', 'rih-KAL-sih-trunt',  'Stubbornly resisting authority or control.', 'The recalcitrant mule would not move.', array['exam','writer'], 'advanced'),
 (40, 'Anticipate',   'an-TIS-ih-payt',     'To expect something and prepare for it.', 'We anticipate heavy traffic on Friday.', array['business','everyday'], 'beginner'),
 (41, 'Inherent',     'in-HAIR-ent',        'Existing as a natural, permanent part of something.', 'Some risk is inherent in any investment.', array['business','exam'], 'intermediate'),
 (42, 'Loquacious',   'loh-KWAY-shus',      'Talking a great deal.', 'My loquacious uncle talked through the whole drive.', array['writer','exam'], 'advanced'),
