 (44, 'Mundane',      'mun-DAYN',           'Ordinary and lacking excitement.', 'She wrote about the mundane details of daily life.', array['everyday','writer'], 'intermediate'),
 (45, 'Vicarious',    'vy-KAIR-ee-us',      'Experienced through someone else''s actions rather than your own.', 'He got vicarious thrills from his sister''s adventures.', array['writer','exam'], 'advanced'),
 (46, 'Genuine',      'JEN-yoo-in',         'Real, honest, and not fake.', 'Her thanks were warm and genuine.', array['everyday'], 'beginner'),
 (47, 'Reticent',     'RET-ih-sent',        'Reluctant to share thoughts or feelings.', 'He was reticent about his plans.', array['exam','writer'], 'intermediate'),
 (48, 'Ebullient',    'ih-BUL-yent',        'Cheerful and full of energy.', 'The ebullient crowd cheered every goal.', array['writer','exam'], 'advanced'),
 (49, 'Mingle',       'MING-gul',           'To mix with other people at a gathering.', 'After dinner, the guests began to mingle.', array['everyday'], 'beginner'),
 (50, 'Tangible',     'TAN-juh-bul',        'Real enough to be seen, touched, or measured.', 'The training led to tangible improvements.', array['business','exam'], 'intermediate'),
 (51, 'Sycophant',    'SIK-uh-fant',        'A person who flatters important people to gain favor.', 'The boss was surrounded by sycophants who never disagreed.', array['exam','writer'], 'advanced'),
 (52, 'Lucid',        'LOO-sid',            'Clear and easy to understand.', 'Her lucid explanation made the topic simple.', array['business','everyday'], 'intermediate'),
 (53, 'Meander',      'mee-AN-der',         'To wander slowly, or to follow a winding course.', 'The river meanders through the valley.', array['writer','everyday'], 'intermediate'),
 (54, 'Fastidious',   'fas-TID-ee-us',      'Very careful about accuracy and detail.', 'A fastidious editor, she checked every comma.', array['business','exam'], 'intermediate'),
 (55, 'Conundrum',    'kuh-NUN-drum',       'A confusing problem that is hard to solve.', 'Choosing between two great job offers was a real conundrum.', array['everyday','writer'], 'intermediate'),
 (56, 'Zealous',      'ZEL-us',             'Full of energy and enthusiasm for a cause.', 'She was a zealous supporter of the local library.', array['writer','exam'], 'intermediate'),
 (57, 'Arduous',      'AR-joo-us',          'Needing a lot of effort and stamina.', 'The arduous climb took six hours.', array['exam','writer'], 'intermediate'),
 (58, 'Boost',        'BOOST',              'To lift or improve something.', 'A good night''s sleep can boost your mood.', array['everyday'], 'beginner'),
 (59, 'Cherish',      'CHAIR-ish',          'To value something deeply and protect it.', 'I cherish the memories of that summer.', array['everyday','writer'], 'beginner')
